class Solution:
    def uniquePaths(self, m, n):
        f = [1] * n
        for _ in range(1, m):
            for j in range(1, n):
                f[j] += f[j - 1]
        return f[-1]

def main():
    m, n = map(int, input().split())
    print(Solution().uniquePaths(m, n))


if __name__ == "__main__":
    main()
